fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1 + hash(999) % 9);
        host::display::state_set(2, 0);
        host::display::state_set(4, 0);
        host::display::state_set(6, 1);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(5) == 0;
    host::display::state_set(5, down);
    let cur: i32 = host::display::state_get(1);
    if host::display::state_get(4) == 1 {
        host::display::clear(0x180808);
        host::display::draw_string(120, 150, "WRONG CALL", 0xff4040, 4);
        host::display::draw_string(120, 210, "IT CAME UP", 0x808080, 2);
        host::display::draw_number(330, 200, cur, 0xffffff, 4);
        host::display::draw_string(120, 270, "STREAK", 0x808080, 2);
        host::display::draw_number(250, 264, host::display::state_get(2), 0xffffff, 3);
        host::display::draw_string(120, 304, "BEST", 0x808080, 2);
        host::display::draw_number(250, 298, host::display::state_get(3), 0x00ff88, 3);
        host::display::draw_string(130, 370, "TAP TO DEAL AGAIN", 0x808080, 2);
        if tap {
            host::display::state_set(0, 0);
        }
    } else {
        if tap {
            let mut up: i32 = 0;
            if host::display::pointer_y() < h / 2 { up = 1; }
            let rnd: i32 = host::display::state_get(6);
            host::display::state_set(6, rnd + 1);
            let next: i32 = 1 + hash(rnd * 7 + 3) % 9;
            let mut correct: i32 = 0;
            if next == cur { correct = 1; }
            if next > cur && up == 1 { correct = 1; }
            if next < cur && up == 0 { correct = 1; }
            host::display::state_set(1, next);
            if correct == 1 {
                let s: i32 = host::display::state_get(2) + 1;
                host::display::state_set(2, s);
                if s > host::display::state_get(3) {
                    host::display::state_set(3, s);
                }
            } else {
                host::display::state_set(4, 1);
            }
        }
        host::display::clear(0x0a1220);
        host::display::fill_rect(0, 0, w, h / 2, 0x122036);
        host::display::draw_string(w / 2 - 60, 40, "HIGHER", 0x6688aa, 3);
        host::display::draw_string(w / 2 - 55, h - 70, "LOWER", 0x6688aa, 3);
        host::display::fill_rect(w / 2 - 55, h / 2 - 75, 110, 150, 0xf0f0e8);
        host::display::draw_number(w / 2 - 18, h / 2 - 30, cur, 0x101010, 8);
        host::display::draw_string(8, 8, "STREAK", 0x808080, 2);
        host::display::draw_number(130, 8, host::display::state_get(2), 0xffffff, 2);
        host::display::draw_string(w - 150, 8, "BEST", 0x808080, 2);
        host::display::draw_number(w - 70, 8, host::display::state_get(3), 0x00ff88, 2);
    }
    host::display::present();
}
